    dict(id='CFG-542', area='cfg', desc="형식 호환 규칙: 기존 None 이면 아무 값, bool 은 bool 끼리만(true↔1 금지), int↔float 호환, 같은 타입, list↔tuple 호환, 나머지 불일치. 불일치 문구 '{sec}.{key}: {새 종류} {새 값 60자} 가 들어 있습니다 — {기존 종류}로 쓰세요 (기본값 예: {기존 값})' — 종류 이름 null/true/false/숫자/따옴표로 감싼 글자/목록([ ... ])/묶음({ ... }).", v1='lib/_config_loader.py:81-104; lib/_config_loader.py:167-189; lib/_config_loader.py:283-288', v2='v2/tools/convert_v1_config.py', test='v2/tests/test_convert_v1_config.py::test_rejected', status='done', note='v2 범위 검사가 더해짐(D11 — v1 클램프 대신 거부)'),
