    dict(id='CFG-544', area='cfg', desc="전부 아니면 전무: 문제가 하나라도 있으면 어떤 값도 setattr 하지 않고 반환. 문제가 없으면 구역별 config 모듈에 setattr, applied 개수 세고 INFO '[ConfigLoader] 설정 로드: {경로} ({n}개 값 적용)'. res.data 는 적용한 json(_plain 으로 보통 dict).", v1='lib/_config_loader.py:451-461', v2='v2/tools/convert_v1_config.py; v2/common/config_store.py', test='v2/tests/test_inv_cfg.py::test_nested_dup_dict_int_keys_and_all_or_nothing', status='done', note='오류가 하나라도 있으면 아무 파일도 쓰지 않음'),
